//! FFI over yptun-core for the mobile apps (Kotlin now, Swift later), generated by uniffi.
//!
//! yptun-core is not touched. Complex models (locations, profiles, settings, routing) cross the
//! boundary as JSON in the same serde shapes the apps already store; small structs read often
//! (plan steps, location/profile info, WARP endpoint, log batches) are typed records; binary
//! data is raw bytes. Settings live parsed inside [CoreSession], so they are not re-parsed per
//! call. Traffic never crosses this boundary. Panics surface as Kotlin InternalException.

uniffi::setup_scaffolding!();

mod api;
mod android;
mod logs;
mod plan;
mod session;

pub use api::*;
pub use android::*;
pub use logs::*;
pub use plan::*;
pub use session::*;

use serde::de::DeserializeOwned;
use serde::Serialize;
use yptun_core::model::ProxyCore;

/// Errors returned to the app (Kotlin: FfiException.Json / Invalid / Unsupported).
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Error)]
#[uniffi(flat_error)]
pub enum FfiError {
    /// A JSON argument did not match the expected model.
    Json(String),
    /// The input parsed but the core rejected it.
    Invalid(String),
    /// The location cannot run on this platform.
    Unsupported(String),
}

impl std::fmt::Display for FfiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Json(m) => write!(f, "invalid JSON: {m}"),
            Self::Invalid(m) | Self::Unsupported(m) => f.write_str(m),
        }
    }
}

impl std::error::Error for FfiError {}

pub(crate) fn from_json<T: DeserializeOwned>(what: &str, json: &str) -> Result<T, FfiError> {
    serde_json::from_str(json).map_err(|e| FfiError::Json(format!("{what}: {e}")))
}

pub(crate) fn to_json<T: Serialize>(value: &T) -> Result<String, FfiError> {
    serde_json::to_string(value).map_err(|e| FfiError::Json(e.to_string()))
}

/// Proxy core choice (Kotlin ProxyCore).
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum CoreKind {
    Auto,
    SingBox,
    Xray,
}

impl From<ProxyCore> for CoreKind {
    fn from(c: ProxyCore) -> Self {
        match c {
            ProxyCore::Auto => Self::Auto,
            ProxyCore::SingBox => Self::SingBox,
            ProxyCore::Xray => Self::Xray,
        }
    }
}

impl From<CoreKind> for ProxyCore {
    fn from(c: CoreKind) -> Self {
        match c {
            CoreKind::Auto => Self::Auto,
            CoreKind::SingBox => Self::SingBox,
            CoreKind::Xray => Self::Xray,
        }
    }
}
